                .packageName("com.example.app")
                .sha256CertFingerprints(List.of("AB:CD:EF:01:23:45:67:89:AB:CD:EF:01:23:45:67:89:AB:CD:EF:01:23:45:67:89:AB:CD:EF:01:23:45:67:89"))
                .build()))
        .build());
